import{_ as a,o as t,c as r,a5 as l}from"./chunks/framework.BwlBv862.js";const u=JSON.parse('{"title":"下载与更新","description":"","frontmatter":{"title":"下载与更新","docId":"user.start.updates","translationKey":"user.start.updates","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6b92351b3ee8eb1b0745db65bbddb3eab21f4ae0a9945795c94147c9ca347e73","translationRevision":"555c4413550154a21df63f410e8e350f90ca8052128ccc61543852d2dee50f2c","order":40},"headers":[],"relativePath":"zh/user/updates.md","filePath":"zh/user/updates.md","lastUpdated":1794611623000}'),o={name:"zh/user/updates.md"};function s(i,e,n,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="downloads-and-updates" tabindex="-1">下载与更新 <a class="header-anchor" href="#downloads-and-updates" aria-label="Permalink to &quot;下载与更新 {#downloads-and-updates}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>选择正确的发布通道，并在更新时区分“检查更新”与“自动安装”。更换版本前，请关闭活动会话并备份本地数据，尤其是在跨越文档明确说明的数据库迁移时。</p><h2 id="select-a-channel" tabindex="-1">选择通道 <a class="header-anchor" href="#select-a-channel" aria-label="Permalink to &quot;选择通道 {#select-a-channel}&quot;">​</a></h2><p><a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">发行版列表</a>会区分稳定版与预发行版。带有 <code>-rc</code> 等后缀的候选版用于验证。应用更新器区分 stable 与 beta 源，提供版本前会验证已签名的元数据。未经签名的 JSON 文件或被修改的安装器不会被接受为有效更新。</p><h2 id="check-and-install" tabindex="-1">检查与安装 <a class="header-anchor" href="#check-and-install" aria-label="Permalink to &quot;检查与安装 {#check-and-install}&quot;">​</a></h2><ol><li>打开 <strong>设置 → 常规</strong>，查看更新器当前状态与已安装版本。</li><li>执行可用的检查。构建若未配置公钥或更新源能力，会显示无法检查。</li><li>阅读发行说明，选择对应平台的安装包。</li><li>构建若提供下载或手动交接流程，请按该流程操作。只有配置仓库公钥变量时，发布流程才启用验证检查；自动安装还有额外开关。</li><li>手动更新时，关闭 TikTools，替换或安装完整且已验证的安装包，然后重新打开。数据目录应与应用文件分开保留。</li></ol><h2 id="expected-result" tabindex="-1">预期结果 <a class="header-anchor" href="#expected-result" aria-label="Permalink to &quot;预期结果 {#expected-result}&quot;">​</a></h2><p>重新启动的应用显示所选版本，并能读取预期的本地配置。便携式 ZIP/TAR 包需要手动替换。即使存在 AppImage 安装器，未知或解压后的目录布局也可能要求手动更新。</p><h2 id="recovery-and-limitations" tabindex="-1">恢复方法与限制 <a class="header-anchor" href="#recovery-and-limitations" aria-label="Permalink to &quot;恢复方法与限制 {#recovery-and-limitations}&quot;">​</a></h2><p>签名检查失败即表示更新失败；请重新下载官方副本并核对发布校验和，不要绕过验证。自动替换 AppImage 和 NSIS 交接各有独立的构建门控，仍属实验性功能。系统没有通用的自动回滚机制。改用旧版二进制文件不会撤销已迁移的 SQLite 结构。</p><p>报告问题时，请提供已安装版本、安装包格式以及诊断中的更新器错误。不要附带签名密钥、邀请令牌或账户数据。<a href="./installation.html">安装指南</a>说明了支持的包目录布局。</p><h2 id="operational-details" tabindex="-1">运行细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;运行细节 {#operational-details}&quot;">​</a></h2><p>更新器能力在构建时固定。检查更新需要配置 feed 与公钥。自动替换 AppImage 还需要通用安装开关及检测到支持的安装；NSIS 同时要求该通用开关和 NSIS 专用开关。安装后设置环境变量不能启用已编译开关。便携/解压/未知布局使用手动替换。真实安装后应确认版本、重启和配置数据；下载、校验和或启动安装器本身不证明完成。</p>',14)])])}const b=a(o,[["render",s]]);export{u as __pageData,b as default};
